/** 工作区下拉清单：切换（逐条）与添加入口（分隔组）。 */
function WorkspaceMenu({
  workspaces,
  onOpen,
  onAdd,
}: {
  workspaces: WorkspaceRecord[];
  onOpen: (root: string) => void;
  onAdd: () => void;
}): React.JSX.Element {
  return (
    <DropdownMenuContent side="right">
      <DropdownMenuGroup>
        <DropdownMenuLabel>工作区</DropdownMenuLabel>
        {workspaces.map((record) => (
          <DropdownMenuItem key={record.root} onClick={() => onOpen(record.root)}>
            {record.name}
          </DropdownMenuItem>
        ))}
      </DropdownMenuGroup>
      <DropdownMenuSeparator />
      <DropdownMenuGroup>
        <DropdownMenuItem onClick={onAdd}>
          <PlusIcon />
          添加工作区
        </DropdownMenuItem>
      </DropdownMenuGroup>
    </DropdownMenuContent>
  );
}

function WorkspaceSelector({
  workspaces,
  currentRoot,
  onOpen,
  onAdd,
}: {
  workspaces: WorkspaceRecord[];
  currentRoot: string;
  onOpen: (root: string) => void;
  onAdd: () => void;
  onRemove: (root: string) => void;
}) {
  if (workspaces.length === 0) {
    return (
      <SidebarMenuItem>
        <SidebarMenuButton size="lg" onClick={onAdd}>
          <span className="flex min-w-0 flex-col leading-tight">
            <span>未关联工作区</span>
            <span>点击添加</span>
          </span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    );
  }
  const currentRecord = workspaces.find((record) => record.root === currentRoot);
  if (!currentRecord) {
    return null;
  }
  const parent = parentDir(currentRecord.root);
  return (
    <SidebarMenuItem>
      <DropdownMenu>
        <DropdownMenuTrigger render={<SidebarMenuButton size="lg" />}>
          <WorkspaceTriggerLabel record={currentRecord} parent={parent} />
        </DropdownMenuTrigger>
        <WorkspaceMenu workspaces={workspaces} onOpen={onOpen} onAdd={onAdd} />
      </DropdownMenu>
    </SidebarMenuItem>
  );
}

export function AppSidebar({
  workspaces,
  currentRoot,
  onOpen,
  onAdd,
  onRemove,
}: AppSidebarProps): React.JSX.Element {
  return (
    <Sidebar collapsible="icon">
      <SidebarGroup>
        <SidebarGroupContent>
          <SidebarMenu>
            <WorkspaceSelector
              workspaces={workspaces}
              currentRoot={currentRoot}
              onOpen={onOpen}
              onAdd={onAdd}
              onRemove={onRemove}
            />
            {currentRoot && <PageNavGroup />}
          </SidebarMenu>
        </SidebarGroupContent>
      </SidebarGroup>
      <SystemToolsGroup />
    </Sidebar>
  );
}

