src/views/architecture/components/elemen.source:
/**
 * 左元素树：层级由 **FQN 最长前缀**派生（父 = 最长已声明前缀，非 TOML 表嵌套），
 * 节点状态点取节点标记词汇（`nodeDot`）。停摆态零节点（由父级全或无停摆承载），
 * 空模型亦零节点。
 */
import { useMemo, useState } from 'react';

import type { ArchiElement } from '../../../types/generated/bindings';
import { shortName } from '../lib/fqn';
import { nodeDot } from '../lib/marks';

export interface ElementTreeProps {
  /** 图元素（FQN 唯一） */
  elements: ArchiElement[];
  /** 当前聚焦元素（1-hop 中心） */
  focused: string | null;
  /** 聚焦切换（纯前端，零取数） */
  onFocus: (fqn: string) => void;
}

/** 父 FQN（最长已声明前缀；顶层返回 null）。 */
function parentOf(fqn: string, known: ReadonlySet<string>): string | null {
  const segments = fqn.split('.');
  while (segments.length > 1) {
    segments.pop();
    const candidate = segments.join('.');
    if (known.has(candidate)) return candidate;
  }
  return null;
}

interface TreeShape {
  roots: string[];
  children: Map<string, string[]>;
}

/** 前缀派生树（元素按 FQN 字典序，兄弟节点稳定序）。 */
function buildTree(elements: ArchiElement[]): TreeShape {
  const known = new Set(elements.map((element) => element.fqn));
  const roots: string[] = [];
  const children = new Map<string, string[]>();
  for (const element of [...elements].sort((left, right) => left.fqn.localeCompare(right.fqn))) {
    const parent = parentOf(element.fqn, known);
    if (parent === null) {
      roots.push(element.fqn);
      continue;
    }
    const siblings = children.get(parent);
    if (siblings === undefined) children.set(parent, [element.fqn]);
    else siblings.push(element.fqn);
  }
  return { roots, children };
}

function TreeNodes({
  fqns,
  byFqn,
  tree,
  focused,
  expanded,
  onFocus,
  onToggle,
}: {
  fqns: string[];
  byFqn: ReadonlyMap<string, ArchiElement>;
  tree: TreeShape;
  focused: string | null;
  expanded: ReadonlySet<string>;
  onFocus: (fqn: string) => void;
  onToggle: (fqn: string) => void;
}): React.JSX.Element {
  return (
    <ul className="m-0 list-none p-0">
      {fqns.map((fqn) => {
        const element = byFqn.get(fqn);
        if (element === undefined) return null;
        const children = tree.children.get(fqn) ?? [];
        const open = expanded.has(fqn);
        return (
          <li className="m-0" key={fqn}>
            <div
              className={`flex items-center gap-1 rounded px-1 py-0.5 text-[13px] ${
                focused === fqn ? 'bg-muted font-medium' : ''
              }`}
            >
              {children.length > 0 ? (
                <button
                  className="w-4 shrink-0 text-muted-foreground"
                  onClick={() => onToggle(fqn)}
                  aria-label={open ? `收起 ${fqn}` : `展开 ${fqn}`}
                >
                  {open ? '▾' : '▸'}
                </button>
              ) : (
                <span className="w-4 shrink-0" />
              )}
              <button
                className="flex min-w-0 items-center gap-1.5 text-left"
                data-testid="archi-tree-node"
                data-fqn={fqn}
                onClick={() => onFocus(fqn)}
                title={fqn}
              >
                <span data-testid="archi-node-mark">{nodeDot(element.mark)}</span>
                <span className="truncate">{shortName(fqn)}</span>
              </button>
            </div>
            {open && children.length > 0 && (
              <div className="ml-4 border-l border-border pl-1">
                <TreeNodes
                  fqns={children}
                  byFqn={byFqn}
                  tree={tree}
                  focused={focused}
                  expanded={expanded}
                  onFocus={onFocus}
                  onToggle={onToggle}
                />
              </div>
            )}
          </li>
        );
      })}
    </ul>
  );
}

export function ElementTree({ elements, focused, onFocus }: ElementTreeProps): React.JSX.Element {
  const tree = useMemo(() => buildTree(elements), [elements]);
  const byFqn = useMemo(
    () => new Map(elements.map((element) => [element.fqn, element])),
    [elements],
  );
  // 缺省展开全部顶层（深层按需展开）；展开集为纯本地态，切换零取数
  const [folded, setFolded] = useState<ReadonlySet<string>>(() => new Set());
  const expanded = useMemo(() => {
    const opened = new Set<string>();
    for (const fqn of tree.children.keys()) {
      if (!folded.has(fqn)) opened.add(fqn);
    }
    return opened;
  }, [tree, folded]);

  const toggle = (fqn: string): void => {
    setFolded((current) => {
      const next = new Set(current);
      if (next.has(fqn)) next.delete(fqn);
      else next.add(fqn);
      return next;
    });
  };

  return (
    <section className="min-h-0 w-52 shrink-0 overflow-auto pr-2" data-testid="archi-element-tree">
      <h2 className="m-0 mb-1.5 text-[13px] font-medium text-muted-foreground">元素</h2>
      {tree.roots.length === 0 ? (
        <div className="text-[13px] text-muted-foreground" data-testid="archi-tree-empty">
          模型内暂无元素
        </div>
      ) : (
        <TreeNodes
          fqns={tree.roots}
          byFqn={byFqn}
          tree={tree}
          focused={focused}
          expanded={expanded}
          onFocus={onFocus}
          onToggle={toggle}
        />
      )}
    </section>
  );
}

src/views/architecture/components/struct.source:
/**
 * 停摆态面板（全或无）：模型有**任何**结构错时，画布与元素树一起停摆，此处逐条
 * 呈现 `kind` + `message` + `file:line` 并提示「修好后再看」。
 *
 * 零图数据、零降级样式、零占位节点——残缺图的读法本身歧义（环画成什么样？悬空
 * 边画在哪？），而结构错都有精确行号，读文本比读畸形图快。
 */
import type { ArchiDiagnostic } from '../../../types/generated/bindings';

/** 位置串：行号未知（`line === 0`）时只渲文件。 */
function position(diagnostic: ArchiDiagnostic): string {
  if (diagnostic.line === 0) return diagnostic.file;
  return `${diagnostic.file}:${diagnostic.line}`;
}

export function StructureErrorPanel({
  diagnostics,
}: {
  diagnostics: ArchiDiagnostic[];
}): React.JSX.Element {
  return (
    <section
      className="rounded-lg border border-fail bg-fail-bg px-4 py-3"
      data-testid="archi-error-panel"
    >
      <h2 className="m-0 mb-2 text-[15px] text-fail">模型结构错（{diagnostics.length} 条）</h2>
      <div className="flex flex-col gap-2">
        {diagnostics.map((diagnostic, index) => (
          <div
            className="break-all text-[13px] text-fail"
            data-testid="archi-error-row"
            key={`${diagnostic.kind}-${position(diagnostic)}-${index}`}
          >
            <div className="font-medium">
              {diagnostic.kind} · {position(diagnostic)}
            </div>
            <pre className="m-0 whitespace-pre-wrap break-words font-mono text-xs">
              {diagnostic.message}
            </pre>
          </div>
        ))}
      </div>
      <div className="mt-2 text-xs text-muted-foreground">
        修好后再看：结构错未消除前不渲染任何图数据（零节点、零边、零降级样式）。
      </div>
    </section>
  );
}

src/views/architecture/hooks/use-archi-g.source:
/**
 * 画布取数 hook：**显式取数**——只在三种触发下发起 invoke（组件挂载 / `root`
 * 变化 / 手动刷新），零目录监听、零轮询、零跨调用缓存（沿既有「显式取数」红线）。
 *
 * 停摆态与正常态同形透出：结构错时后端返回零图数据 + 诊断清单，本 hook 只做透传
 * （停摆判据 = `diagnostics` 非空，不在前端二次判定）。`root` 为 null（壳态无根）
 * 时不发 invoke。
 */
import { useCallback, useEffect, useState } from 'react';

import { commands, type ArchiGraph } from '../../../types/generated/bindings';

export interface ArchiGraphState {
  /** 画布数据（停摆/正常两态；无根或首轮未回为 null） */
  graph: ArchiGraph | null;
  /** 取数进行中 */
  loading: boolean;
  /** 取数失败（命令 reject，行内持久呈现） */
  error: string | null;
  /** 手动刷新（第三种触发；唯一显式入口） */
  refresh: () => void;
}

export function useArchiGraph(root: string | null): ArchiGraphState {
  const [graph, setGraph] = useState<ArchiGraph | null>(null);
  const [loadedRoot, setLoadedRoot] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [tick, setTick] = useState(0);

  const refresh = useCallback(() => setTick((value) => value + 1), []);

  useEffect(() => {
    if (root === null) {
      setGraph(null);
      setLoadedRoot(null);
      setLoading(false);
      setError(null);
      return;
    }
    let cancelled = false;
    setLoading(true);
    setError(null);
    commands
      .archiGraph(root)
      .then((result) => {
        if (cancelled) return;
        setGraph(result);
        setLoadedRoot(root);
        setLoading(false);
      })
      .catch((reason: unknown) => {
        if (cancelled) return;
        setError(String(reason));
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [root, tick]);

  return { graph: loadedRoot === root ? graph : null, loading, error, refresh };
}

src/views/architecture/hooks/use-archi-m.source:
/**
 * 抽屉取数 hooks：元素详情（`archi_module`，`fqn` 变化即重取）与文档正文
 * （`archi_read_doc`，展开才发 invoke）。两者都走显式取数（零 watch 零轮询）；
 * 正文取数只接受关联集内路径——越界由服务端 `Err`，本层只呈现错误串。
 */
import { useCallback, useEffect, useState } from 'react';

import { commands, type ArchiModuleDetail } from '../../../types/generated/bindings';

export interface ArchiModuleState {
  /** 元素详情（无根 / 无选中为 null） */
  detail: ArchiModuleDetail | null;
  /** 取数进行中 */
  loading: boolean;
  /** 取数失败（命令 reject） */
  error: string | null;
}

export function useArchiModule(root: string | null, fqn: string | null): ArchiModuleState {
  const [detail, setDetail] = useState<ArchiModuleDetail | null>(null);
  const [loadedKey, setLoadedKey] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (root === null || fqn === null) {
      setDetail(null);
      setLoadedKey(null);
      setLoading(false);
      setError(null);
      return;
    }
    const key = `${root}\u0000${fqn}`;
    let cancelled = false;
    setLoading(true);
    setError(null);
    commands
      .archiModule(root, fqn)
      .then((result) => {
        if (cancelled) return;
        setDetail(result);
        setLoadedKey(key);
        setLoading(false);
      })
      .catch((reason: unknown) => {
        if (cancelled) return;
        setError(String(reason));
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [root, fqn]);

  const currentKey = root === null || fqn === null ? null : `${root}\u0000${fqn}`;
  return { detail: loadedKey === currentKey ? detail : null, loading, error };
}

export interface ArchiDocState {
  /** 正文（未展开 / 已复位为 null） */
  body: string | null;
  /** 取数进行中 */
  loading: boolean;
  /** 取数失败（越界 / 读盘失败，行内呈现） */
  error: string | null;
  /** 展开时显式取正文 */
  load: (path: string) => void;
  /** 收起 / 切换条目时清态 */
  reset: () => void;
}

export function useArchiDoc(root: string | null): ArchiDocState {
  const [body, setBody] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const reset = useCallback(() => {
    setBody(null);
    setLoading(false);
    setError(null);
  }, []);

  const load = useCallback(
    (path: string) => {
      if (root === null) {
        setError('无工作根，无法读取文档');
        return;
      }
      setBody(null);
      setLoading(true);
      setError(null);
      commands
        .archiReadDoc(root, path)
        .then((text) => {
          setBody(text);
          setLoading(false);
        })
        .catch((reason: unknown) => {
          setError(String(reason));
          setLoading(false);
        });
    },
    [root],
  );

  return { body, loading, error, load, reset };
}

src/views/architecture/lib/fqn.ts.source:
/**
 * FQN 展示映射（纯函数，单点）：末段短名由元素树与画布节点共用同一取法——两处各
 * 写一份会各自演化（一处按 `.` 切分、一处按首字母缩写），同一元素在树与画布上呈现
 * 不同名字。
 */
export function shortName(fqn: string): string {
  const segments = fqn.split('.');
  return segments[segments.length - 1] ?? fqn;
}

src/views/architecture/lib/marks.ts.source:
/**
 * 漂移标记 → 视觉映射（封闭词汇，纯函数）。
 *
 * 边四值：`none` 实线（本期恒此值）/ `unfulfilled` 灰虚线 / `crossKind` 橙虚线 /
 * `exempt` 灰实线；节点两值：`unfulfilled` 🟡 / 其余 ⚪。词汇**外**的值退化为中性
 * 样式且不抛错（标记扩展走「改能力 spec + 同步对拍语料」两处，不得静默新增）。
 *
 * 标记的**产生**（何时算漂移）不在本模块——本期生产者恒空，渲染契约先立。
 */
export interface EdgeVisual {
  /** 描边色（CSS 变量，随主题） */
  stroke: string;
  /** 虚线模式（null = 实线） */
  dasharray: string | null;
}

/**
 * 边标记 → 描边视觉；词汇外与 `none` 同款中性。
 *
 * 入参按 `string` 收面（`EdgeMark` 是其子集）：词汇封闭由退化分支承载——运行时
 * 拿到的词汇外值不崩溃、不空白，扩展词汇仍须「改能力 spec + 同步对拍语料」两处。
 */
export function edgeVisual(mark: string): EdgeVisual {
  switch (mark) {
    case 'unfulfilled':
      return { stroke: 'var(--muted-foreground)', dasharray: '6 4' };
    case 'crossKind':
      return { stroke: 'var(--warn)', dasharray: '4 3' };
    case 'exempt':
      return { stroke: 'var(--muted-foreground)', dasharray: null };
    default:
      return { stroke: 'var(--chart-2)', dasharray: null };
  }
}

/**
 * 节点标记 → 状态点；词汇外一律 ⚪ 正常（同 `edgeVisual` 的退化口径：`NodeMark`
 * 两值是 `string` 的子集，退化分支即词汇封闭的执行点）。
 */
export function nodeDot(mark: string): string {
  return mark === 'unfulfilled' ? '🟡' : '⚪';
}

