class ResizeObserverStub {
  observe = vi.fn();
  unobserve = vi.fn();
  disconnect = vi.fn();
}

function stubEnvironment() {
  vi.stubGlobal('ResizeObserver', ResizeObserverStub);
  return () => {
    vi.unstubAllGlobals();
  };
}

