describe('正常态：缺省 1-hop 渲染面', () => {
  it('应渲染三段布局并以首个顶层元素为聚焦（抽屉 fqn 与取数参数一致）', async () => {
    render(<ArchitectureCanvas root={'C:\\demo\\alpha'} mode="full" />);
