describe('抽屉取数态与 gate 编辑边界', () => {
  it('应在 ADR 正文取数未回时呈现加载行（不空白、不提前显错误）', async () => {
    let resolveDoc: ((body: string) => void) | undefined;
    invokeMock.mockImplementation((command: string) => {
      if (command === 'archi_module') {
        return Promise.resolve({
          element: element(),
          dependsOn: [],
          dependedBy: [],
          children: [],
          docs: docsFixture(),
          warnings: [],
        });
      }
